/**
 * Returns the chapter list for a given grade and subject ID.
 */
export function getSubjectChapters(grade, subjectId, subjectName = '') {
  const gKey = String(grade);
  if (DAV_CHAPTERS[gKey]) {
    // 1. Direct key match
    if (DAV_CHAPTERS[gKey][subjectId] && DAV_CHAPTERS[gKey][subjectId].length > 0) {
      return DAV_CHAPTERS[gKey][subjectId];
    }
    // 2. Specific verified aliases for language sub-books
    if (subjectId === 'eng8_lit' && DAV_CHAPTERS[gKey]['eng8']) return DAV_CHAPTERS[gKey]['eng8'];
    if (subjectId === 'hin8_gs' && DAV_CHAPTERS[gKey]['hin8']) return DAV_CHAPTERS[gKey]['hin8'];
    if (subjectId === 'hin8_as' && DAV_CHAPTERS[gKey]['hin8_as']) return DAV_CHAPTERS[gKey]['hin8_as'];
    if (subjectId === 'hin7_as' && DAV_CHAPTERS[gKey]['hin7_as']) return DAV_CHAPTERS[gKey]['hin7_as'];
    if (subjectId === 'hin7' && DAV_CHAPTERS[gKey]['hin7_gs']) return DAV_CHAPTERS[gKey]['hin7_gs'];
    if (subjectId === 'hin6' && DAV_CHAPTERS[gKey]['hin6_gs']) return DAV_CHAPTERS[gKey]['hin6_gs'];
    if (subjectId === 'hin5' && DAV_CHAPTERS[gKey]['hin5_bm']) return DAV_CHAPTERS[gKey]['hin5_bm'];
    if (subjectId === 'hin4' && DAV_CHAPTERS[gKey]['hin4_bm']) return DAV_CHAPTERS[gKey]['hin4_bm'];
    if (subjectId === 'hin4_ba' && DAV_CHAPTERS[gKey]['hin4_ba']) return DAV_CHAPTERS[gKey]['hin4_ba'];
    if (subjectId === 'hin3' && DAV_CHAPTERS[gKey]['hin3_bm']) return DAV_CHAPTERS[gKey]['hin3_bm'];
    if (subjectId === 'hin3_ba' && DAV_CHAPTERS[gKey]['hin3_ba']) return DAV_CHAPTERS[gKey]['hin3_ba'];
    if (subjectId === 'hin2' && DAV_CHAPTERS[gKey]['hin2_bm']) return DAV_CHAPTERS[gKey]['hin2_bm'];
    if (subjectId === 'hin2_bm' && DAV_CHAPTERS[gKey]['hin2_bm']) return DAV_CHAPTERS[gKey]['hin2_bm'];
    if (subjectId === 'hin2_ba' && DAV_CHAPTERS[gKey]['hin2_ba']) return DAV_CHAPTERS[gKey]['hin2_ba'];
    if (subjectId === 'hin1' && DAV_CHAPTERS[gKey]['hin1_bm']) return DAV_CHAPTERS[gKey]['hin1_bm'];
    if (subjectId === 'hin1_bm' && DAV_CHAPTERS[gKey]['hin1_bm']) return DAV_CHAPTERS[gKey]['hin1_bm'];
    if (subjectId === 'hin1_ba' && DAV_CHAPTERS[gKey]['hin1_ba']) return DAV_CHAPTERS[gKey]['hin1_ba'];
    if (subjectId === 'eng7' && DAV_CHAPTERS[gKey]['eng7_lit']) return DAV_CHAPTERS[gKey]['eng7_lit'];
    if (subjectId === 'eng6' && DAV_CHAPTERS[gKey]['eng6_lit']) return DAV_CHAPTERS[gKey]['eng6_lit'];
    if (subjectId === 'eng5' && DAV_CHAPTERS[gKey]['eng5_reader']) return DAV_CHAPTERS[gKey]['eng5_reader'];
    if (subjectId === 'eng4' && DAV_CHAPTERS[gKey]['eng4_reader']) return DAV_CHAPTERS[gKey]['eng4_reader'];
    if (subjectId === 'eng3' && DAV_CHAPTERS[gKey]['eng3_reader']) return DAV_CHAPTERS[gKey]['eng3_reader'];
    if (subjectId === 'eng2' && DAV_CHAPTERS[gKey]['eng2_reader']) return DAV_CHAPTERS[gKey]['eng2_reader'];
    if (subjectId === 'eng1' && DAV_CHAPTERS[gKey]['eng1']) return DAV_CHAPTERS[gKey]['eng1'];
    if (subjectId === 'ukg_hin_bm' && DAV_CHAPTERS[gKey]['ukg_hin_bm']) return DAV_CHAPTERS[gKey]['ukg_hin_bm'];
    if (subjectId === 'ukg_hin_sa' && DAV_CHAPTERS[gKey]['ukg_hin_sa']) return DAV_CHAPTERS[gKey]['ukg_hin_sa'];
    if (subjectId === 'ukg_eng' && DAV_CHAPTERS[gKey]['ukg_eng']) return DAV_CHAPTERS[gKey]['ukg_eng'];
    if (subjectId === 'lkg_eng' && DAV_CHAPTERS[gKey]['lkg_eng']) return DAV_CHAPTERS[gKey]['lkg_eng'];
  }

  // Fallback if custom subject requested
  const defaultCount = grade === 8 || grade === '8' ? 16 : 10;
  const list = [];
  for (let i = 1; i <= defaultCount; i++) {
    list.push({
      number: i,
      title: `Chapter ${i}: ${subjectName} Practice Solutions`,
      tagline: `DAV Class ${grade} curriculum exercise solutions, short Q&A and workbook solutions`,
      icon: 'BookOpen',
      emoji: '📘',
      badge: 'Curriculum Unit 🌟',
      solutionGyanUrl: '',
      learnCramUrl: '',
      ncertUrl: '',
      onlineHindiUrl: ''
    });
  }
  return list;
}

/**
 * Builds guaranteed direct working URLs for each academic portal.
 * NEVER puts query text in search bars - directly lands on chapter or subject solutions.
 */
export function buildProviderUrls(grade, subject, chapter) {
  if (!subject || !chapter) return {};

  const gNum = String(grade);
  const sId = subject?.id || '';

  // 1. Solution Gyan: Direct Chapter Page OR Direct Subject Hub (NO search bar)
  const directSolutionGyan = chapter.solutionGyanUrl || '';
  const solutionGyanHub = (SOLUTION_GYAN_HUBS[gNum] && SOLUTION_GYAN_HUBS[gNum][sId])
    || `https://solutiongyan.com/dav-class-${grade}/`;

  // 2. Learn Cram: Direct Chapter Worksheet/Solution OR Subject Hub (NO search bar)
  const directLearnCram = chapter.learnCramUrl || '';
  const learnCramHub = (LEARN_CRAM_HUBS[gNum] && LEARN_CRAM_HUBS[gNum][sId])
    || `https://www.learncram.com/dav-solutions/dav-books-solutions-class-${grade}/`;

  // 3. Online Hindi (A Guide to Hindi by Avinash Ranjan Gupta)
  const directOnlineHindi = chapter.onlineHindiUrl || '';
  const onlineHindiHub = 'https://www.onlinehindi.in/';

  // 4. NCERT Book Solutions / PDF Portal
  const directNcert = chapter.ncertUrl || '';
  const ncertHub = 'https://ncertbookspdf.com/';

  return {
    solutionGyan: directSolutionGyan || solutionGyanHub,
    solutionGyanIsDirect: Boolean(directSolutionGyan),
    solutionGyanHub,

    learnCram: directLearnCram || learnCramHub,
    learnCramIsDirect: Boolean(directLearnCram),
    learnCramHub,

    onlineHindi: directOnlineHindi || onlineHindiHub,
    onlineHindiIsDirect: Boolean(directOnlineHindi),
    onlineHindiHub,

    ncertBookPdf: directNcert || '',
    ncertIsDirect: Boolean(directNcert),
    ncertHub
  };
}
